-- Cosmetics: restore the Cosmetics skill line (779) for every character.
-- It stays put now that the classless login sweep no longer unlearns line 779 (see the world
-- migration of the same id).
DELETE FROM `character_skills` WHERE `skill` = 779;
INSERT INTO `character_skills` (`guid`, `skill`, `value`, `max`)
SELECT `guid`, 779, 1, 400 FROM `characters`;

